use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_or_comma(c: char) -> bool {
    ('a' <= c && c <= 'z') || c == ','
}

spec fn expected_output_char(input_char: char) -> char {
    if input_char == ',' {
        ' '
    } else {
        input_char
    }
}

fn solve(s: Vec<char>) -> (result: Vec<char>)
    requires
        s.len() == 19,
        forall |i: int| 0 <= i < s.len() ==> is_lowercase_or_comma(s[i]),
        s[5] == ',',
        s[13] == ',',
    ensures
        result.len() == 20,
        result[19] == '\n',
        forall |i: int| 0 <= i < 19 ==> result[i] == expected_output_char(s[i]),
{
    let mut result: Vec<char> = Vec::new();
    
    // Process first 19 characters
    let mut i: usize = 0;
    while i < 19
        invariant
            0 <= i <= 19,
            result.len() == i,
            forall |j: int| 0 <= j < i ==> result[j] == expected_output_char(s[j]),
    {
        let c = s[i];
        let output_char = if c == ',' { ' ' } else { c };
        result.push(output_char);
        i = i + 1;
    }
    
    // Add newline character
    result.push('\n');
    
    result
}

}
